package com.procurement.rfq.specification; import com.procurement.rfq.entity.*; import org.springframework.data.jpa.domain.Specification; public final class RfqLineSpecification{private RfqLineSpecification(){}public static Specification<RfqLine> search(Long rfqId,Long productId){return(r,q,b)->{var p=b.conjunction();if(rfqId!=null)p=b.and(p,b.equal(r.get("rfq").get("id"),rfqId));if(productId!=null)p=b.and(p,b.equal(r.get("product").get("id"),productId));return p;};}}
